const Article = require('../models/article');
const SubCategory = require('../models/subCategory');
const Category = require('../models/category');
const User = require('../models/user');
const fs = require('fs');
const path = require('path');

exports.getAllArticles = async (req, res) => {
  try {
    const articles = await Article.findAll({
      include: [
        { model: SubCategory, as: 'subcategory', include: [{ model: Category, as: 'category' }] },
        { model: User, as: 'author' }
      ],
      order: [['createdAt', 'DESC']]
    });
    res.json({ success: true, articles });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false });
  }
};

exports.getArticleById = async (req, res) => {
  try {
    const article = await Article.findByPk(req.params.id, {
      include: [
        { model: SubCategory, as: 'subcategory', include: [{ model: Category, as: 'category' }] },
        { model: User, as: 'author' }
      ]
    });
    if (!article) return res.status(404).json({ success: false, message: 'Not found' });
    res.json({ success: true, article });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false });
  }
};

exports.createArticle = async (req, res) => {
  try {
    const { title, content, subCategoryId } = req.body;
    const image = req.file ? req.file.filename : null;
    const authorId = req.user.id;

    const newArticle = await Article.create({ title, content, subCategoryId, authorId, image });
    res.json({ success: true, article: newArticle });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false });
  }
};

exports.updateArticle = async (req, res) => {
  try {
    const article = await Article.findByPk(req.params.id);
    if (!article) return res.status(404).json({ success: false, message: 'Not found' });

    const { title, content, subCategoryId } = req.body;
    const image = req.file ? req.file.filename : article.image;

    await article.update({ title, content, subCategoryId, image });
    res.json({ success: true, article });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false });
  }
};

exports.deleteArticle = async (req, res) => {
  try {
    const article = await Article.findByPk(req.params.id);
    if (!article) return res.status(404).json({ success: false, message: 'Not found' });

    await article.destroy();
    res.json({ success: true, message: 'Deleted successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false });
  }
};

